"""Explicit transformation definitions; generation fails for an unspecified output."""
from generate import *

def fields(n):return {c['name']:c for c in MODELS[n]['columns']}
def key(domain,*args):
    parts=[q(domain)]
    for arg in args:
        name,typ,expr=arg if isinstance(arg,tuple) else (arg,'String',arg)
        value='toUnixTimestamp64Milli('+expr+')' if 'DateTime' in typ else 'toUInt8('+expr+')' if 'Bool' in typ else expr
        string='toDecimalString('+expr+','+str(int(typ.split(',')[-1].replace(')','')))+')' if 'Decimal' in typ else 'toString('+value+')'
        parts.append('tuple('+q(name)+','+q(typ)+",if(isNull("+expr+"),'1','0'),ifNull("+string+",''))")
    return 'lower(hex(SHA256(toJSONString(materialize(tuple('+','.join(parts)+'))))))'
def ts(v):return j("utc_var('"+v+"')")
RUN=j("ch_literal(var('model_run_id','parse_only'))")
CUTOFF=ts('input_cutoff_at')
BOUND=ts('case_as_of_boundary_at')
RULE=j("ch_literal(var('rule_version','parse_only'))")
TENANT=j("ch_literal(var('source_tenant_id','demo_crm'))")

def source_cte(n,alias='s'):
    m=MODELS[n];cols=[c['name'] for c in m['columns']]+[x[0] for x in ST]
    condition='capture_at <= '+CUTOFF
    if not n.startswith('stg_boond_'):
        domain='.'.join(m['source'])
        condition+=" and capture_key in ({% for k in var('source_capture_keys', {}).get("+repr(domain)+",[]) %}{{ ch_literal(k) }}{{ ',' if not loop.last }}{% else %}''{% endfor %})"
    return alias+' as (select '+cols_sql(cols)+' from '+ref(n)+' where '+condition+')'
def history(n,alias='s'):
    # Boundaries formed before deletion filtering or array expansion.
    return source_cte(n,'admitted')+',\n'+alias+' as (select '+cols_sql([c['name'] for c in MODELS[n]['columns']]+[x[0] for x in ST])+", leadInFrame(toNullable(src_published_at)) over (partition by source_identity_key order by src_published_at rows between unbounded preceding and unbounded following) as source_next_at from admitted)"
def lineage(alias='s'):
    return dict(source_published_at=alias+'.src_published_at',source_version_keys='['+alias+'.source_version_key]')
def combined_lineage(*aliases,raw=()):
    dates=[a+'.source_published_at' for a in aliases]+[a+'.src_published_at' for a in raw]
    arrays=['ifNull('+a+'.source_version_keys,[])' for a in aliases]+['['+a+'.source_version_key]' for a in raw]
    return dict(source_published_at='greatest('+','.join(dates)+')' if len(dates)>1 else dates[0],source_version_keys='arraySort(arrayDistinct(arrayFilter(x->x is not null,arrayConcat('+','.join(arrays)+'))))' if len(arrays)>1 else arrays[0])
def build(n,expr,from_sql,ctes='',grain=None):
    m=MODELS[n];columns=fields(n);business=[c for c in columns if c not in R]
    missing=set(business)-set(expr)
    if missing:raise ValueError(n+' unspecified outputs: '+','.join(sorted(missing)))
    if grain is None:
        grain_match=re.search(r'(?:record_key=|record_key en est l.alias.*?)(\w+_key)',m['block'])
        grain=next((c for c in business if c.endswith('_version_key') and c!='source_version_keys'),None)
    if isinstance(grain,str):rk=grain
    elif isinstance(grain,list):rk=key(n+':grain',*[(c,columns[c]['type'],c) for c in grain])
    else:raise ValueError('Missing grain '+n)
    tags=['dtr'] if n.startswith('dtr_') else ['common'] if n.startswith('dim_') or m['schema']=='dwh_common' else ['pipeline'] if m['schema']=='dwh_pipeline' else ['revenue']
    config=j("config(materialized='incremental', incremental_strategy='append', engine='MergeTree()', schema="+repr(m['schema'])+", unique_key='record_version_key', order_by=['model_run_id','record_key'], full_refresh=false, on_schema_change='fail', tags="+repr(tags)+")")
    select=',\n    '.join('CAST('+expr[c]+' AS '+columns[c]['type']+') AS `'+c+'`' for c in business)
    payload=hash_expr(n+':row_v1',[(c,columns[c]['type'],c) for c in business])
    rv=key('record_version_v1',('model_run_id','String','model_run_id'),('record_key','String','record_key'))
    sql=config+'\n'+j('assert_case_vars()')+'\nwith '+(ctes+',\n' if ctes else '')+'business as (select\n    '+select+'\nfrom '+from_sql+'),\nidentified as (select\n    '+cols_sql(business)+',\n    '+RUN+' as model_run_id,\n    '+rk+' as record_key,\n    '+payload+' as row_hash,\n    '+ts('calculated_at')+' as calculated_at,\n    '+RULE+' as rule_version,\n    '+CUTOFF+' as input_cutoff_at\nfrom business),\ncandidate as (select\n    '+cols_sql([c for c in columns if c!='record_version_key'])+',\n    '+rv+' as record_version_key\nfrom identified)\n'
    # One candidate evaluation: reject divergent matches, omit identical matches, append missing keys.
    # This filtered LEFT JOIN is an anti-join with an immutable-content assertion on matched rows.
    sql+='select\n    '+cols_sql(list(columns),'c')+'\nfrom candidate c\n{% if is_incremental() %}\nleft join (select model_run_id,record_key,row_hash from '+j('this')+' where model_run_id='+RUN+') t on c.model_run_id=t.model_run_id and c.record_key=t.record_key\nwhere if(t.record_key is null,true,throwIf(c.row_hash!=t.row_hash,\'Immutable run content diverged\')!=0)\n{% endif %}\n'
    # Partition only the completed logical rows, before the wide payload serialization.
    # All windows/joins in business remain complete. The default partition is the whole run.
    start=sql.index('identified as (select')
    end=sql.index('candidate as (select',start)
    keyed_cols=business+['model_run_id','record_key','calculated_at','rule_version','input_cutoff_at']
    keyed='keyed as (select\n    '+cols_sql(business)+',\n    '+RUN+' as model_run_id,\n    '+rk+' as record_key,\n    '+ts('calculated_at')+' as calculated_at,\n    '+RULE+' as rule_version,\n    '+CUTOFF+' as input_cutoff_at,\n    cityHash64(record_key) % '+j("var('write_batch_count',1)|int")+' as __write_bucket\nfrom business),\nselected_rows as (select '+cols_sql(keyed_cols)+' from keyed where __write_bucket='+j("var('write_batch_index',0)|int")+'),\nidentified as (select '+cols_sql(keyed_cols)+',\n    '+payload+' as row_hash from selected_rows),\n'
    sql=sql[:start]+keyed+sql[end:]
    sql='\n'.join('-- depends_on: '+ref(dep) for dep in m['refs'])+'\n'+sql
    write(m['path'],sql)

def temporal_dim(n,src,entity,extra,ctes_extra='',from_extra=''):
    e=dict(**lineage(),tenant_id='s.src_tenant_id',**{entity+'_id':'s.src_id'},valid_from_at='s.src_published_at',valid_to_at='s.source_next_at',is_source_deleted='s.src_is_deleted')
    e[entity+'_key']=key(entity+'_v1',('tenant_id','String','s.src_tenant_id'),(entity+'_id','Int64','s.src_id'))
    e[entity+'_version_key']=key(entity+'_version_v1',(entity+'_key','String',e[entity+'_key']),('valid_from_at',"DateTime64(3,'UTC')",'s.src_published_at'))
    e.update(extra)
    build(n,e,'s'+from_extra,history(src)+ctes_extra,entity+'_version_key')

